<template><view class="page"><view class="card"><text class="title">邀请家庭成员</text><text class="sub">添加后可共同查看老人状态并参与照护</text><text class="label">姓名</text><input v-model="form.name" class="input" placeholder="例如：小强"/><text class="label">手机号</text><input v-model="form.phone" class="input" type="number" maxlength="11" placeholder="请输入手机号"/><text class="label">与老人关系</text><picker :range="relations" @change="e=>relationIndex=e.detail.value"><view class="input picker">{{relations[relationIndex]}}</view></picker><text class="label">成员角色</text><picker :range="roles" @change="e=>roleIndex=e.detail.value"><view class="input picker">{{roles[roleIndex]}}</view></picker><button class="save" @tap="submit">发送邀请</button></view></view></template><script>export default{data(){return{form:{name:'',phone:''},relations:['儿子','女儿','配偶','孙辈','其他'],relationIndex:0,roles:['家庭成员','主要照护人','紧急联系人'],roleIndex:0}},methods:{submit(){if(!this.form.name.trim()||!/^1\d{10}$/.test(this.form.phone))return uni.showToast({title:'请填写完整信息',icon:'none'});const list=uni.getStorageSync('invited_members')||[];list.push({...this.form,relation:this.relations[this.relationIndex],role:this.roles[this.roleIndex]});uni.setStorageSync('invited_members',list);uni.showToast({title:'邀请已创建',icon:'success'});setTimeout(()=>uni.navigateBack(),500)}}}</script><style scoped>.page{min-height:100vh;padding:28rpx;background:#f6f7f3}.card{padding:30rpx;background:#fff;border-radius:28rpx}.title{display:block;font-size:34rpx;font-weight:900}.sub{display:block;margin:10rpx 0 26rpx;color:#7d8881;font-size:21rpx}.label{display:block;margin:22rpx 0 10rpx;color:#66766d;font-size:22rpx}.input{height:82rpx;padding:0 20rpx;background:#f4f6f3;border-radius:18rpx}.picker{line-height:82rpx}.save{margin-top:32rpx;background:#326a53;color:#fff;border-radius:20rpx}</style>